var coords, figs;

function setup() {
	// createCanvas(windowWidth, windowHeight);
	if (windowWidth / 0.75 > windowHeight) {
	  createCanvas(windowHeight, windowHeight * 0.75);	
	} else {
	  createCanvas(windowHeight, windowHeight / 0.75);	
	}
	describe("morph between molecular structures"); // Examples of Homologous series
  colorMode(RGB, 255)
	background(color(2, 2, 8)); // bg

	textAlign(CENTER, CENTER)
	describe("random line walker with triangle angles possible forming hexagons (partially), color from position in green/blue slowly fading out");
  frameRate(60);

	noFill()
  strokeWeight(1); // ~~random(3, 5.7));

	coords = genCoords(PX, PY);
	figs = getFigure(0);
	// console.log(figs);

	textStyle(BOLD);
	textSize(~~(abs(coords[0].y-coords[1].y)/2));

  loop();
}

