	if (frameCount % (3*60) === 0) {
		figs = getFigure(~frameCount/(3*60))
	}

	text(figs.name, width/2, height - 3 * textSize())

	// add padding to center drawing
	translate((width-coords[PX-1].x)/2, (height-max(coords[coords.length-1].y, coords[coords.length-2].y))/2)

	if (false) {		
		noFill();
		stroke("darkgrey");
		strokeWeight(1);
		beginShape()
		// for (let p of coords) vertex(p.x, p.y)
		for (let i = 0; i < coords.length; i++) {
			p = coords[i];
			text(i, p.x, p.y)
			vertex(p.x, p.y)
		}
		endShape()
	}

	noFill();
	stroke("darkred")
	strokeWeight(4);
	// paths
	for (let lines of figs.path) {
		if (true) {
var f = (frameCount % 100) / 100;
			// console.log(f)
var l = lines.length-1;
var i1 = lines[~~(f*l)];
var i2 = lines[~~(f*l)+1];
var p = fract(f*l);
			stroke(figs.clr); // stroke("darkred")
			line(coords[i1].x, coords[i1].y, coords[i2].x, coords[i2].y);
			stroke("white")
			point(lerp(coords[i1].x, coords[i2].x, p), lerp(coords[i1].y, coords[i2].y, p));
		} else {			
			beginShape();
			for (let pi of lines) vertex(coords[pi].x, coords[pi].y);
			endShape();
		}
	}
	// pois
	{	
		noStroke()
		strokeWeight(2);
var FS = textSize();
var PAD = ~~(FS/8);
		for (let poi of figs.pois) {
			rectMode(CENTER);
			fill("white")
			rect(coords[poi[0]].x, coords[poi[0]].y, textWidth(poi[1])+PAD, FS+PAD)
			fill(figs.clr); // "darkred"
			text(poi[1], coords[poi[0]].x, coords[poi[0]].y);
		}
	}


}


function genCoords(PX, PY) {
var pts = [];
var r = ~~((width / PX) / 1.1); // TODO proof formula
var sa = PI + PI/6;
var da = TWO_PI/6;
	// gen points, starting top left, top mid, top right, bt, bm, bl
	for (let a = 0; a < TWO_PI - da/2; a+=da) {
var x = cos(a+sa) * r;
var y = sin(a+sa) * r;
		pts.push({x, y});
	}
	// switch points bl and br
	[pts[3],pts[5]] = [pts[5],pts[3]];

var dx = pts[0].x;
var dy = pts[1].y;
	for (let p of pts) {
		p.x -= dx;
		p.y -= dy;
	}
	// console.log(pts); // circle points

var res = [];
	// 1st row
	for (let i = 0; i < PX; i++) {
		res[i] = {x: pts[i%2].x, y: pts[i%2].y};
		res[i].x = i * pts[1].x;
	}
	// 2nd row: same x, y's from pts[4..5]
	if (PY > 1) {
		for (let i = 0; i < PX; i++) {
			res[i+PX] = {x: res[i].x, y: pts[i%2+3].y};
		}
	}
	// duplicate further rows
	if (PY > 2) {
		var dy = (res[PX+1].y - res[1].y) + (res[PX+2].y - res[2].y)		
		for (let i = 0; i < PX * (PY-2); i++) {
			res[i+PX+PX] = {x: res[i%PX].x, y: res[i].y+dy};
		}
	}
	// console.log(res); // arry points [0..PX*PY-1]

	return res;
}

