function clrLine(x1, y1, x2, y2, c1, c2) {
	// const easings = [easeInOutElastic, easeInOutCubic, easeInCubic];
	// const easing = random(easings);
var dst = dist(x1, y1, x2, y2);
	for (let i = 0; i <= dst; i++) {
		var f = i/dst;
		var x = lerp(x1, x2, f);
		var y = lerp(y1, y2, f);
var c = lerpColor(c1, c2, f); // easing(f);
		stroke(c);
		point(x, y);
	}
}

